create table public.user_settings(user_id uuid primary key default auth.uid(), timezone text not null default 'Asia/Kolkata', start_date date not null default current_date, daily_goal_minutes int not null default 180, weekly_goal_minutes int not null default 1080, dsa_target_minutes int not null default 60, learning_target_minutes int not null default 90, project_target_minutes int not null default 90, github_username text, leetcode_username text, preferred_language text default 'Python', leetcode_daily_target int default 2, leetcode_weekly_target int default 10, updated_at timestamptz not null default now());
create table public.topic_progress(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), topic_id text not null, status text not null default 'Not Started' check (status in ('Not Started','In Progress','Completed','Needs Revision')), confidence int check (confidence between 1 and 5), notes text, revision_notes text, next_revision date, actual_minutes int not null default 0, completed_at timestamptz, updated_at timestamptz not null default now(), unique(user_id,topic_id));
create table public.topic_submissions(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), topic_id text not null, slot int not null check (slot between 1 and 3), title text, description text, repo_url text, live_url text, demo_url text, technologies text, status text not null default 'Not Started' check (status in ('Not Started','In Progress','Completed','Needs Improvement')), est_hours numeric, actual_hours numeric, start_date date, completion_date date, notes text, lessons text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,topic_id,slot));
create table public.study_sessions(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), date date not null, start_at timestamptz, end_at timestamptz, minutes int not null check (minutes >= 0), planned_minutes int, category text not null, month_id int, topic_id text, description text, status text not null default 'Completed', confidence int check (confidence between 1 and 5), notes text, resource_url text, commit_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index on public.study_sessions(user_id,date);
create table public.active_timers(user_id uuid primary key default auth.uid(), started_at timestamptz not null default now(), category text not null, topic_id text, description text);
create table public.milestone_progress(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), milestone_id int not null, status text not null default 'Not Started' check (status in ('Not Started','Planning','In Progress','Testing','Deployed','Completed')), repo_url text, live_url text, demo_url text, start_date date, deadline date, actual_hours numeric, tech_stack text, lessons text, readme_done boolean not null default false, tests_done boolean not null default false, confirmed_complete boolean not null default false, updated_at timestamptz not null default now(), unique(user_id,milestone_id));
create table public.criterion_checks(user_id uuid not null default auth.uid(), criterion_id text not null, checked_at timestamptz not null default now(), primary key(user_id,criterion_id));
create table public.project_tasks(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), milestone_id int not null, title text not null, done boolean not null default false, done_at timestamptz, created_at timestamptz not null default now());
create table public.resource_status(user_id uuid not null default auth.uid(), resource_id text not null, status text not null default 'Not Started', notes text, rating int check (rating between 1 and 5), updated_at timestamptz not null default now(), primary key(user_id,resource_id));
create table public.dsa_problems(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), problem_id text, title text not null, platform text not null default 'LeetCode', url text, difficulty text not null default 'Easy' check (difficulty in ('Easy','Medium','Hard')), topic text, status text not null default 'To Do' check (status in ('To Do','Attempted','Solved','Needs Revision')), date_attempted date, date_solved date, minutes int, attempts int not null default 0, language text, solution_notes text, mistakes text, complexity text, next_revision date, solution_url text, confidence int check (confidence between 1 and 5), source text not null default 'manual', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.github_repos(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), full_name text not null, url text not null, description text, language text, visibility text, stars int, forks int, gh_created_at timestamptz, gh_updated_at timestamptz, month_id int, topic_id text, deploy_url text, source text not null default 'manual', synced_at timestamptz, created_at timestamptz not null default now(), unique(user_id,full_name));
create table public.sync_logs(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), service text not null, ok boolean not null, message text, created_at timestamptz not null default now());
create table public.weekly_reviews(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), week_start date not null, achievements text, difficult text, mistakes text, lessons text, revisit text, priorities text[] not null default '{}', updated_at timestamptz not null default now(), unique(user_id,week_start));

do $$ declare t text; begin
foreach t in array array['user_settings','topic_progress','topic_submissions','study_sessions','active_timers','milestone_progress','criterion_checks','project_tasks','resource_status','dsa_problems','github_repos','sync_logs','weekly_reviews'] loop
  execute format('grant select,insert,update,delete on public.%I to authenticated', t);
  execute format('grant all on public.%I to service_role', t);
  execute format('alter table public.%I enable row level security', t);
  execute format('create policy "own rows" on public.%I for all to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id)', t);
end loop; end $$;